@echo off
title Nexus-226 Terminal Environment
cd /d "%~dp0"
echo ========================================================
echo  Nexus-226 Virtual Environment Activated (.venv)
echo  Available Commands:
echo    python main.py --mode voice     (Always-on voice call)
echo    python main.py --mode text      (Interactive terminal)
echo    streamlit run web_ui.py         (Browser Web GUI)
echo    python control_panel.py         (Desktop Controller)
echo    python test_nexus_suite.py      (Run all unit tests)
echo ========================================================
call .venv\Scripts\activate.bat
cmd /k

@echo off
title Nexus-226 Master Control Panel
cd /d "%~dp0"
echo [Nexus-226] Launching Master Control Panel...
python control_panel.py
if %ERRORLEVEL% NEQ 0 (
    echo.
    echo ======================================================
    echo An error occurred launching the control panel.
    echo Error code: %ERRORLEVEL%
    echo ======================================================
    pause
)

@echo off
title Nexus-Grok AI Starter
cd /d "%~dp0"
echo ========================================================
echo   Starting Nexus-Grok AI Cockpit
echo ========================================================
echo.
echo Launching browser to http://localhost:8501 ...
start "" "http://localhost:8501"
"%~dp0.venv\Scripts\python.exe" -m streamlit run "%~dp0web_ui.py" --server.port 8501 --server.headless true --browser.gatherUsageStats false --server.fileWatcherType none --client.toolbarMode minimal
if %ERRORLEVEL% NEQ 0 (
    echo.
    echo Trying fallback python...
    python -m streamlit run "%~dp0web_ui.py" --server.port 8501 --server.headless true --browser.gatherUsageStats false --server.fileWatcherType none --client.toolbarMode minimal
)
pause

@echo off
title Nexus-Grok Voice Call Loop
cd /d "%~dp0"
echo ========================================================
echo   Connecting Always-On Real-Time Voice Call
echo ========================================================
echo.
"%~dp0.venv\Scripts\python.exe" "%~dp0main.py" --mode voice
pause

