import os
import sys
import re
import json
from typing import Dict, Any, Optional, Generator

root_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if root_dir not in sys.path:
    sys.path.insert(0, root_dir)

from core.knowledge_base import AIKnowledgeEngine
from core.system_controller import SystemController
from core.blockchain_manager import BlockchainManager
from core.llm_engine import OfflineLLMEngine
from core.grok_engine import GrokEngine

class Nexus226Agent:

    def __init__(self):
        self.knowledge = AIKnowledgeEngine()
        self.sys_controller = SystemController()
        self.blockchain = BlockchainManager()
        self.llm = OfflineLLMEngine()
        self.grok = GrokEngine(mode="fun")

    def process_request(self, user_query: str) -> str:
        q = user_query.strip()
        ql = q.lower()

        if not ql:
            return "Listening. Say or type a command."

        if ql in ["hello", "hi", "hey", "good morning", "good evening", "howdy", "greetings"]:
            return "Greetings! Nexus-Grok online and listening. Ask me any question, run code, or command machine actions."

        if any(ql == w or ql == f"{w} grok" or ql == f"{w} nexus" for w in ["who are you", "what are you", "what is your name"]):
            return "I am Nexus-Grok, your uncensored offline autonomous AI agent equipped with 226 AI architecture paradigms, OS machine controls, blockchain treasury, and voice duplex."

        if any(ql.startswith(w) for w in ["how are you", "are you ready", "are you online", "status", "are you working"]):
            return "All systems operational and hot in memory. Ready for commands or complex inquiries."

        if ql in ["thank you", "thanks", "thanks grok", "appreciate it"]:
            return "You're welcome! Ready for the next command."

        if ql in ["help", "what can you do", "commands", "menu"]:
            return "Capabilities: 226 AI paradigms, live web intelligence, python sandbox ('python: ...'), Wake-on-LAN, screenshots, hardware telemetry, crypto wallet, and voice interaction."

        if ql.startswith("set mode to ") or ql.startswith("switch mode to "):
            m = ql.replace("set mode to ", "").replace("switch mode to ", "").strip()
            if m in ["fun", "think", "normal"]:
                self.grok.set_mode(m)
                return f"Grok mode set to {m.upper()}."

        if ql.startswith("run code:") or ql.startswith("python:") or ql.startswith("execute code:"):
            code = q.split(":", 1)[1].strip()
            res = self.grok.execute_python_code(code)
            if res.get("success"):
                return f"Output:\n{res.get('output')}"
            return f"Error:\n{res.get('error')}"

        if any(w in ql for w in ["generate image", "create graphic", "draw ", "render image"]):
            prompt = q
            for prefix in ["generate image of", "generate image", "create graphic of", "create graphic", "draw"]:
                if prefix in ql:
                    prompt = ql.split(prefix, 1)[1].strip()
                    break
            img_path = self.grok.generate_visual_graphic(prompt)
            return f"Graphic rendered: {img_path}"

        if any(w in ql for w in ["search web", "look up", "google ", "browse web", "latest news"]):
            search_query = q
            for prefix in ["search web for", "search web", "look up", "browse web for", "latest news on"]:
                if prefix in ql:
                    search_query = ql.split(prefix, 1)[1].strip()
                    break
            web_res = self.grok.search_web_or_feed(search_query)
            snippets = "\n".join([f"- {s}" for s in web_res.get("results", [])[:3]])
            return f"Live Intel for '{search_query}':\n{snippets}"

        if any((w in ql for w in ["wake on lan", "wol", "open computer", "open the computer", "wake computer", "power on"])):
            mac_match = re.search("([0-9a-fA-F]{2}[:-]){5}([0-9a-fA-F]{2})", q)
            if mac_match:
                mac = mac_match.group(0)
                res = self.sys_controller.send_wake_on_lan(mac)
                return f"Wake-on-LAN Signal Broadcasted: {res.get('message', res)}"
            return "Provide target MAC address (e.g. 'Wake computer 00:1A:2B:3C:4D:5E')."

        if "schedule wake" in ql or "wake at" in ql:
            time_match = re.search("(\\d{1,2}:\\d{2})", q)
            if time_match:
                t = time_match.group(1)
                res = self.sys_controller.schedule_wake_timer(t)
                return f"Wake alarm set for {t}."
            return "Specify time in HH:MM format."

        if "sleep computer" in ql or "suspend machine" in ql:
            return "Entering low-power sleep mode."

        if any((w in ql for w in ["system status", "telemetry", "hardware status", "pc specs", "ram usage", "battery"])):
            t = self.sys_controller.get_telemetry()
            return f"Hardware: CPU {t['cpu_usage_percent']}% | RAM {t['ram_available_gb']}GB free of {t['ram_total_gb']}GB ({t['ram_used_percent']}% used) | Battery {t['battery']['percent']}%"

        if "screenshot" in ql:
            path = "screenshot.png"
            res = self.sys_controller.capture_screenshot(path)
            if res.get("success"):
                return f"Screenshot captured: {res['path']}"
            return f"Screenshot error: {res.get('error')}"

        if ql.startswith("run powershell ") or ql.startswith("powershell "):
            cmd = q.split("powershell", 1)[1].strip()
            res = self.sys_controller.run_powershell(cmd)
            return res.get("stdout") or res.get("stderr") or "[Executed]"

        if ql.startswith("launch ") or ql.startswith("open app "):
            app = q.replace("open app", "").replace("launch", "").strip()
            res = self.sys_controller.launch_app(app)
            return str(res.get("message", res.get("error")))

        if "list processes" in ql:
            procs = self.sys_controller.list_processes(limit=6)
            return "\n".join([f"- PID {p['pid']}: {p['name']} ({p['memory_mb']} MB)" for p in procs])

        if any((w in ql for w in ["wallet", "balance", "crypto balance", "my address"])):
            b = self.blockchain.get_balance()
            return f"Treasury: Address {b['address']} | Balance {b['balance']} AETH | Ledger: {len(self.blockchain.ledger)} blocks"

        if any((w in ql for w in ["send ", "transfer ", "pay "])) and any((w in ql for w in ["tokens", "eth", "aeth", "to "])):
            amt_match = re.search("(\\d+(?:\\.\\d+)?)", q)
            addr_match = re.search("(0x[a-fA-F0-9]{40})", q)
            if amt_match and addr_match:
                amt = float(amt_match.group(1))
                addr = addr_match.group(1)
                tx_res = self.blockchain.create_and_sign_transaction(addr, amt, memo=f"Transfer: {q[:30]}")
                if tx_res.get("success"):
                    return f"Mined Block #{tx_res['block_index']}! Sent {tx_res['amount']} AETH to {tx_res['to'][:10]}... | New Balance: {tx_res['new_balance']} AETH"
                return f"Transaction Failed: {tx_res.get('error')}"
            return "Specify amount and 0x address."

        if "transaction history" in ql or "ledger" in ql:
            txs = self.blockchain.get_transaction_history(limit=4)
            if not txs:
                return "No transactions in ledger."
            return "\n".join([f"- Block #{t.get('block_index')}: {t.get('amount')} AETH -> {t.get('to')[:10]}..." for t in txs])

        matched_domains = self.knowledge.query(q, top_k=1)
        k_ctx = ""
        if matched_domains and any(tok in ql for tok in matched_domains[0].get("name").lower().split()[:2]):
            d = matched_domains[0]
            k_ctx = f"Reference: {d['concept']}"

        system_instruction = (
            f"You are Grok ({self.grok.mode} mode). Direct 1-sentence answer only. "
            "NEVER repeat the question, never say 'You asked', 'According to', or repeat what was read. "
            "Give only the answer."
        )
        user_prompt = f"{k_ctx}\nQuestion: {q}\nDirect Answer:" if k_ctx else f"Question: {q}\nDirect Answer:"

        if self.llm.active_backend in ["ollama", "openai_compatible"]:
            res = self.llm.generate(user_prompt, system_prompt=system_instruction, max_tokens=26)
            if res and not res.startswith("[Ollama") and not res.startswith("[Local"):
                clean = re.sub(r'^(Direct Answer:|Answer:|Grok:|Response:|Question:)\s*', '', res, flags=re.IGNORECASE).strip()
                return clean

        if k_ctx:
            return matched_domains[0]['concept']

        return "Operational. What would you like to explore or execute next?"

    def process_request_stream(self, user_query: str) -> Generator[str, None, None]:
        q = user_query.strip()
        ql = q.lower()

        if not ql:
            yield "Listening. Say or type a command."
            return

        if ql in ["hello", "hi", "hey", "good morning", "good evening", "howdy", "greetings"]:
            yield "Greetings! Nexus-Grok online and listening. Ask me any question, run code, or command machine actions."
            return

        if any(ql == w or ql == f"{w} grok" or ql == f"{w} nexus" for w in ["who are you", "what are you", "what is your name"]):
            yield "I am Nexus-Grok, your uncensored offline autonomous AI agent equipped with 226 AI architecture paradigms, OS machine controls, blockchain treasury, and voice duplex."
            return

        if any(ql.startswith(w) for w in ["how are you", "are you ready", "are you online", "status", "are you working"]):
            yield "All systems operational and hot in memory. Ready for commands or complex inquiries."
            return

        if ql in ["thank you", "thanks", "thanks grok", "appreciate it"]:
            yield "You're welcome! Ready for the next command."
            return

        if ql in ["help", "what can you do", "commands", "menu"]:
            yield "Capabilities: 226 AI paradigms, live web intelligence, python sandbox ('python: ...'), Wake-on-LAN, screenshots, hardware telemetry, crypto wallet, and voice interaction."
            return

        fast_keywords = [
            "set mode to ", "switch mode to ", "run code:", "python:", "execute code:",
            "generate image", "create graphic", "draw ", "render image",
            "search web", "look up", "google ", "browse web", "latest news",
            "wake on lan", "wol", "open computer", "open the computer", "wake computer", "power on",
            "schedule wake", "wake at", "sleep computer", "suspend machine",
            "system status", "telemetry", "hardware status", "pc specs", "ram usage", "battery",
            "screenshot", "run powershell ", "powershell ", "launch ", "open app ",
            "list processes", "wallet", "balance", "crypto balance", "my address",
            "send ", "transfer ", "pay ", "transaction history", "ledger"
        ]
        if any(w in ql for w in fast_keywords):
            yield self.process_request(user_query)
            return

        matched_domains = self.knowledge.query(q, top_k=1)
        k_ctx = ""
        if matched_domains and any(tok in ql for tok in matched_domains[0].get("name").lower().split()[:2]):
            d = matched_domains[0]
            k_ctx = f"Reference: {d['concept']}"

        system_instruction = (
            f"You are Grok ({self.grok.mode} mode). Direct 1-sentence answer only. "
            "NEVER repeat the question, never say 'You asked', 'According to', or repeat what was read. "
            "Give only the answer."
        )
        user_prompt = f"{k_ctx}\nQuestion: {q}\nDirect Answer:" if k_ctx else f"Question: {q}\nDirect Answer:"

        if self.llm.active_backend in ["ollama", "openai_compatible"]:
            first_chunk = True
            for chunk in self.llm.generate_stream(user_prompt, system_prompt=system_instruction, max_tokens=26):
                if first_chunk:
                    chunk = re.sub(r'^(Direct Answer:|Answer:|Grok:|Response:|Question:)\s*', '', chunk, flags=re.IGNORECASE)
                    first_chunk = False
                if chunk:
                    yield chunk
            return

        yield self.process_request(user_query)

import os
import json
import time
import hmac
import hashlib
import secrets
from typing import Dict, Any, List, Optional
WALLETS_DIR = os.path.join(os.path.dirname(__file__), '..', 'wallets')
LEDGER_FILE = os.path.join(os.path.dirname(__file__), '..', 'data', 'blockchain_ledger.json')

class BlockchainManager:

    def __init__(self, wallets_dir: str=WALLETS_DIR, ledger_file: str=LEDGER_FILE):
        self.wallets_dir = os.path.abspath(wallets_dir)
        self.ledger_file = os.path.abspath(ledger_file)
        os.makedirs(self.wallets_dir, exist_ok=True)
        os.makedirs(os.path.dirname(self.ledger_file), exist_ok=True)
        self.active_wallet: Optional[Dict[str, str]] = None
        self.ledger: List[Dict[str, Any]] = []
        self._load_ledger()
        self._init_default_wallet()

    @staticmethod
    def _keccak_or_sha256(data: bytes) -> str:
        return hashlib.sha256(data).hexdigest()

    def generate_wallet(self, label: str='primary', passphrase: str='') -> Dict[str, str]:
        priv_key_bytes = secrets.token_bytes(32)
        priv_hex = priv_key_bytes.hex()
        pub_digest = hashlib.sha256(b'PUB_KEY_SALT:' + priv_key_bytes).digest()
        address_raw = hashlib.sha256(pub_digest).hexdigest()[-40:]
        address = '0x' + address_raw
        wallet_data = {'label': label, 'address': address, 'created_at': time.time(), 'chain_compatibility': ['Ethereum', 'Polygon', 'Arbitrum', 'LocalChain']}
        if passphrase:
            salt = secrets.token_hex(16)
            kdf = hashlib.pbkdf2_hmac('sha256', passphrase.encode(), salt.encode(), 100000)
            stream_key = hashlib.sha256(kdf).digest()
            encrypted_priv = bytes((a ^ b for a, b in zip(priv_key_bytes, stream_key))).hex()
            wallet_data['encrypted_private_key'] = encrypted_priv
            wallet_data['salt'] = salt
            wallet_data['encrypted'] = True
        else:
            wallet_data['private_key'] = priv_hex
            wallet_data['encrypted'] = False
        keystore_path = os.path.join(self.wallets_dir, f'{label}_wallet.json')
        with open(keystore_path, 'w', encoding='utf-8') as f:
            json.dump(wallet_data, f, indent=2)
        self.active_wallet = {'label': label, 'address': address, 'private_key': priv_hex}
        return {'label': label, 'address': address, 'status': 'Wallet created and secured', 'keystore_path': keystore_path}

    def _init_default_wallet(self):
        default_file = os.path.join(self.wallets_dir, 'primary_wallet.json')
        if os.path.exists(default_file):
            try:
                with open(default_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    self.active_wallet = {'label': data.get('label', 'primary'), 'address': data.get('address', '0x0000000000000000000000000000000000000000'), 'private_key': data.get('private_key', '')}
            except Exception:
                self.generate_wallet('primary')
        else:
            self.generate_wallet('primary')

    def _load_ledger(self):
        if os.path.exists(self.ledger_file):
            try:
                with open(self.ledger_file, 'r', encoding='utf-8') as f:
                    self.ledger = json.load(f)
            except Exception:
                self.ledger = []
        else:
            self.ledger = []
        if not self.ledger:
            genesis_block = {'block_index': 0, 'timestamp': time.time(), 'transactions': [], 'previous_hash': '0' * 64, 'nonce': 42, 'block_hash': hashlib.sha256(b'GENESIS_BLOCK_NEXUS_226').hexdigest()}
            self.ledger.append(genesis_block)
            self._save_ledger()

    def _save_ledger(self):
        with open(self.ledger_file, 'w', encoding='utf-8') as f:
            json.dump(self.ledger, f, indent=2)

    def get_balance(self, address: Optional[str]=None) -> Dict[str, Any]:
        target_addr = address or (self.active_wallet['address'] if self.active_wallet else None)
        if not target_addr:
            return {'address': None, 'balance': 0.0}
        balance = 1000.0
        for block in self.ledger:
            for tx in block.get('transactions', []):
                if tx.get('to', '').lower() == target_addr.lower():
                    balance += float(tx.get('amount', 0.0))
                if tx.get('from', '').lower() == target_addr.lower():
                    balance -= float(tx.get('amount', 0.0)) + float(tx.get('fee', 0.0))
        return {'address': target_addr, 'balance': round(balance, 4), 'symbol': 'AETH (Nexus Autonomous Token)'}

    def create_and_sign_transaction(self, to_address: str, amount: float, memo: str='', fee: float=0.001) -> Dict[str, Any]:
        if not self.active_wallet:
            return {'success': False, 'error': 'No active wallet loaded.'}
        sender = self.active_wallet['address']
        priv_key = self.active_wallet.get('private_key', '')
        curr_balance = self.get_balance(sender)['balance']
        total_debit = amount + fee
        if curr_balance < total_debit:
            return {'success': False, 'error': f'Insufficient funds: Balance is {curr_balance}, required {total_debit}'}
        tx_payload = {'from': sender, 'to': to_address, 'amount': float(amount), 'fee': float(fee), 'timestamp': time.time(), 'nonce': len(self.ledger), 'memo': memo}
        payload_str = json.dumps(tx_payload, sort_keys=True)
        tx_hash = hashlib.sha256(payload_str.encode()).hexdigest()
        sig = hmac.new(priv_key.encode() if priv_key else b'offline_key', tx_hash.encode(), hashlib.sha256).hexdigest()
        tx_payload['signature'] = sig
        tx_payload['tx_hash'] = tx_hash
        new_block = self._mine_block([tx_payload])
        return {'success': True, 'tx_hash': tx_hash, 'signature': sig, 'block_index': new_block['block_index'], 'block_hash': new_block['block_hash'], 'from': sender, 'to': to_address, 'amount': amount, 'new_balance': self.get_balance(sender)['balance'], 'memo': memo}

    def _mine_block(self, transactions: List[Dict[str, Any]]) -> Dict[str, Any]:
        prev_block = self.ledger[-1]
        prev_hash = prev_block['block_hash']
        block_index = len(self.ledger)
        nonce = 0
        while True:
            candidate = f'{block_index}:{prev_hash}:{json.dumps(transactions)}:{nonce}'
            b_hash = hashlib.sha256(candidate.encode()).hexdigest()
            if b_hash.startswith('00'):
                break
            nonce += 1
        block = {'block_index': block_index, 'timestamp': time.time(), 'transactions': transactions, 'previous_hash': prev_hash, 'nonce': nonce, 'block_hash': b_hash}
        self.ledger.append(block)
        self._save_ledger()
        return block

    def get_transaction_history(self, limit: int=10) -> List[Dict[str, Any]]:
        all_txs = []
        for block in reversed(self.ledger):
            for tx in block.get('transactions', []):
                tx_copy = dict(tx)
                tx_copy['block_index'] = block['block_index']
                all_txs.append(tx_copy)
                if len(all_txs) >= limit:
                    return all_txs
        return all_txs
if __name__ == '__main__':
    bm = BlockchainManager()
    print('Active Wallet:', bm.active_wallet)
    print('Initial Balance:', bm.get_balance())
    res = bm.create_and_sign_transaction('0x71C8360537B882E130420666060021b59E874da7', 25.5, memo='Autonomous Cloud Compute Payment')
    print('Transaction Result:', res)
    print('Updated Balance:', bm.get_balance())

import os
import sys
import io
