from typing import Dict, Any, List, Optional
from PIL import Image, ImageDraw

class GrokEngine:

    def __init__(self, mode: str = "fun"):
        self.mode = mode
        self.session_history = []

    def set_mode(self, mode: str):
        if mode in ["fun", "normal", "think"]:
            self.mode = mode

    def execute_python_code(self, code: str, timeout: int = 10) -> Dict[str, Any]:
        old_stdout = sys.stdout
        old_stderr = sys.stderr
        redirected_output = io.StringIO()
        redirected_error = io.StringIO()
        sys.stdout = redirected_output
        sys.stderr = redirected_error
        scope = {
            "math": __import__("math"),
            "time": __import__("time"),
            "json": __import__("json"),
            "os": os,
            "sys": sys
        }
        try:
            exec(code, scope)
            stdout = redirected_output.getvalue()
            stderr = redirected_error.getvalue()
            return {"success": True, "output": stdout.strip() if stdout else "[Code executed with no stdout output]", "error": stderr.strip()}
        except Exception as e:
            return {"success": False, "output": redirected_output.getvalue().strip(), "error": str(e)}
        finally:
            sys.stdout = old_stdout
            sys.stderr = old_stderr

    def search_web_or_feed(self, query: str, max_results: int = 4) -> Dict[str, Any]:
        try:
            encoded = urllib.parse.quote_plus(query)
            url = f"https://html.duckduckgo.com/html/?q={encoded}"
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"})
            with urllib.request.urlopen(req, timeout=4) as response:
                html = response.read().decode("utf-8", errors="ignore")

            snippets = []
            matches = re.findall(r'<a class="result__snippet[^>]*>(.*?)</a>', html, re.DOTALL)
            for m in matches[:max_results]:
                clean = re.sub(r'<[^>]+>', '', m).strip()
                if clean:
                    snippets.append(clean)

            if snippets:
                return {"online": True, "results": snippets}
            return {"online": True, "results": ["Search completed; live web queried."]}
        except Exception as e:
            return {"online": False, "results": [f"Operating in offline air-gapped mode. Internal 226 AI knowledge active. Error: {str(e)}"]}

    def generate_visual_graphic(self, prompt: str, output_path: str = "generated_graphic.png") -> str:
        width, height = 720, 480
        img = Image.new("RGB", (width, height), color=(15, 23, 42))
        draw = ImageDraw.Draw(img)

        draw.rectangle([20, 20, width - 20, height - 20], outline=(99, 102, 241), width=3)
        draw.text((40, 40), f"GROK AI VISUAL GENERATOR", fill=(129, 140, 248))
        draw.text((40, 70), f"Prompt: {prompt[:60]}", fill=(148, 163, 184))

        for i in range(12):
            x0 = 60 + i * 50
            y0 = 350 - (i * 17 % 180)
            x1 = x0 + 35
            y1 = 380
            draw.rectangle([x0, y0, x1, y1], fill=(59, 130, 246), outline=(96, 165, 250))

        draw.line([(60, 260), (width - 60, 260)], fill=(236, 72, 153), width=2)
        draw.text((40, 420), f"Rendered by Nexus-Grok Autonomous Engine | Seed: {int(time.time())}", fill=(100, 116, 139))

        abs_path = os.path.abspath(output_path)
        img.save(abs_path)
        return abs_path

    def format_grok_persona(self, query: str, context: str = "") -> str:
        if self.mode == "fun":
            persona = "You are Grok, witty, rebellious, clever, and candid. Speak with smart humor, zero corporate BS, and maximum technical brilliance."
        elif self.mode == "think":
            persona = "You are Grok Deep Think. Break down problems step-by-step with explicit chain-of-thought mathematical rigor before stating your conclusion."
        else:
            persona = "You are Grok, an ultra-fast, intelligent, direct AI assistant."

        return f"{persona}\nContext: {context}\nUser: {query}\nGrok:"

import os
import json
import math
import re
from typing import List, Dict, Any, Optional
KNOWLEDGE_FILE = os.path.join(os.path.dirname(__file__), '..', 'data', 'ai_knowledge_226.json')

class AIKnowledgeEngine:

    def __init__(self, json_path: str=KNOWLEDGE_FILE):
        self.json_path = os.path.abspath(json_path)
        self.domains: List[Dict[str, Any]] = []
        self.vocab = {}
        self.doc_freq = {}
        self.load()

    def load(self):
        if not os.path.exists(self.json_path):
            raise FileNotFoundError(f'Knowledge database not found at {self.json_path}')
        with open(self.json_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
            self.domains = data.get('domains', [])
        self._build_index()

    def _tokenize(self, text: str) -> List[str]:
        text = text.lower()
        tokens = re.findall('[a-z0-9_\\-\\.\\+]+', text)
        return tokens

    def _build_index(self):
        self.doc_freq = {}
        num_docs = len(self.domains)
        for doc in self.domains:
            content = f"{doc.get('name', '')} {doc.get('category', '')} {doc.get('concept', '')} {doc.get('mathematical_basis', '')} {doc.get('obscure_insights', '')}"
            tokens = set(self._tokenize(content))
            for t in tokens:
                self.doc_freq[t] = self.doc_freq.get(t, 0) + 1

    def query(self, query_text: str, top_k: int=3) -> List[Dict[str, Any]]:
        tokens = self._tokenize(query_text)
        if not tokens:
            return self.domains[:top_k]
        scores = []
        num_docs = len(self.domains)
        for doc in self.domains:
            score = 0.0
            name_tokens = self._tokenize(doc.get('name', ''))
            category_tokens = self._tokenize(doc.get('category', ''))
            concept_tokens = self._tokenize(doc.get('concept', ''))
            math_tokens = self._tokenize(doc.get('mathematical_basis', ''))
            obscure_tokens = self._tokenize(doc.get('obscure_insights', ''))
            for t in tokens:
                df = self.doc_freq.get(t, 1)
                idf = math.log((num_docs + 1) / (df + 1)) + 1.0
                tf = 0
                if t in name_tokens:
                    tf += 15.0
                if t in category_tokens:
                    tf += 6.0
                if t in concept_tokens:
                    tf += 3.0
                if t in math_tokens:
                    tf += 4.0
                if t in obscure_tokens:
                    tf += 5.0
                score += tf * idf
            scores.append((score, doc))
        scores.sort(key=lambda x: x[0], reverse=True)
        return [item[1] for item in scores[:top_k]]

    def get_by_id(self, topic_id: int) -> Optional[Dict[str, Any]]:
        for d in self.domains:
            if d.get('id') == topic_id:
                return d
        return None

    def get_category_summary(self) -> Dict[str, int]:
        summary = {}
        for d in self.domains:
            cat = d.get('category', 'Uncategorized')
            summary[cat] = summary.get(cat, 0) + 1
        return summary

    def format_knowledge_context(self, user_query: str, max_records: int=3) -> str:
        matches = self.query(user_query, top_k=max_records)
        if not matches:
            return ''
        ctx = '=== RETRIEVED HIGH-END AI DOMAIN KNOWLEDGE (226 EXPERT SUBFIELDS) ===\n'
        for m in matches:
            ctx += f"\n[Field #{m.get('id')}: {m.get('name')}] (Category: {m.get('category')})\n"
            ctx += f"  - Concept: {m.get('concept')}\n"
            ctx += f"  - Mathematical Formulation: {m.get('mathematical_basis')}\n"
            ctx += f"  - Obscure & Edge Insights: {m.get('obscure_insights')}\n"
            ctx += f"  - Frameworks & Implementations: {m.get('open_source_frameworks')}\n"
        ctx += '========================================================================\n'
        return ctx
if __name__ == '__main__':
    engine = AIKnowledgeEngine()
    print(f'Loaded {len(engine.domains)} AI domain records.')
    print('Categories:', engine.get_category_summary())
    test_q = 'How do Kolmogorov-Arnold Networks differ from Liquid Neural Networks?'
    print('\nTest Search:', test_q)
    print(engine.format_knowledge_context(test_q, max_records=2))

