        self.ollama_url = ollama_url
        self.ollama_model = ollama_model
        self.openai_compatible_url = openai_compatible_url
        self.gguf_path = gguf_path
        self.active_backend = self._detect_backend()
        self.warmup_thread = threading.Thread(target=self.warmup, daemon=True)
        self.warmup_thread.start()

    def _detect_backend(self) -> str:
        if self.backend != "auto":
            return self.backend
        try:
            r = requests.get(f"{self.ollama_url}/api/tags", timeout=0.6)
            if r.status_code == 200:
                models = [m.get("name") for m in r.json().get("models", [])]
                if models:
                    if any("1b" in m.lower() for m in models):
                        self.ollama_model = next((m for m in models if "1b" in m.lower()))
                    else:
                        self.ollama_model = models[0]
                return "ollama"
        except Exception:
            pass
        try:
            r = requests.get(f"{self.openai_compatible_url}/models", timeout=0.4)
            if r.status_code == 200:
                return "openai_compatible"
        except Exception:
            pass
        return "builtin_synthesizer"

    def warmup(self):
        if self.active_backend == "ollama":
            try:
                requests.post(
                    f"{self.ollama_url}/api/generate",
                    json={
                        "model": self.ollama_model,
                        "prompt": "ok",
                        "options": {"num_predict": 1, "num_thread": 4, "num_ctx": 256},
                        "keep_alive": -1,
                        "stream": False
                    },
                    timeout=25
                )
            except Exception:
                pass

    def generate(self, prompt: str, system_prompt: str = "", max_tokens: int = 26, temperature: float = 0.3) -> str:
        backend = self.active_backend
        if backend == "ollama":
            return self._call_ollama(prompt, system_prompt, max_tokens, temperature)
        elif backend == "openai_compatible":
            return self._call_openai(prompt, system_prompt, max_tokens, temperature)
        else:
            return self._call_builtin(prompt, system_prompt)

    def generate_stream(self, prompt: str, system_prompt: str = "", max_tokens: int = 26, temperature: float = 0.3) -> Generator[str, None, None]:
        if self.active_backend == "ollama":
            url = f"{self.ollama_url}/api/generate"
            payload = {
                "model": self.ollama_model,
                "prompt": prompt,
                "system": system_prompt or "You are Grok. Direct 1-sentence answer only. Never repeat the question or quote anything.",
                "stream": True,
                "keep_alive": -1,
                "options": {
                    "num_predict": min(max_tokens, 26),
                    "repeat_penalty": 1.25,
                    "num_thread": 4,
                    "num_ctx": 256,
                    "temperature": temperature,
                    "top_k": 25,
                    "top_p": 0.85,
                    "stop": ["\n\n", "User:", "\nUser", "Question:", "Direct Answer:"]
                }
            }
            try:
                with requests.post(url, json=payload, stream=True, timeout=20) as resp:
                    for line in resp.iter_lines():
                        if line:
                            data = json.loads(line)
                            tok = data.get("response", "")
                            if tok:
                                yield tok
                            if data.get("done"):
                                break
            except Exception as e:
                yield f"[Ollama Connection Error]: {e}"
        else:
            yield self.generate(prompt, system_prompt, max_tokens, temperature)

    def _call_ollama(self, prompt: str, system_prompt: str, max_tokens: int, temperature: float) -> str:
        try:
            url = f"{self.ollama_url}/api/generate"
            payload = {
                "model": self.ollama_model,
                "prompt": prompt,
                "system": system_prompt or "You are Grok. Direct 1-sentence answer only. Never repeat the question or quote anything.",
                "stream": False,
                "keep_alive": -1,
                "options": {
                    "num_predict": min(max_tokens, 26),
                    "repeat_penalty": 1.25,
                    "num_thread": 4,
                    "num_ctx": 256,
                    "temperature": temperature,
                    "top_k": 25,
                    "top_p": 0.85,
                    "stop": ["\n\n", "User:", "\nUser", "Question:", "Direct Answer:"]
                }
            }
            res = requests.post(url, json=payload, timeout=20)
            if res.status_code == 200:
                return res.json().get("response", "").strip()
            return f"[Ollama Error] HTTP {res.status_code}"
        except Exception as e:
            return f"[Ollama Connection Error]: {e}"

    def _call_openai(self, prompt: str, system_prompt: str, max_tokens: int, temperature: float) -> str:
        try:
            url = f"{self.openai_compatible_url}/chat/completions"
            messages = []
            if system_prompt:
                messages.append({"role": "system", "content": system_prompt})
            messages.append({"role": "user", "content": prompt})
            payload = {"messages": messages, "max_tokens": min(max_tokens, 26), "temperature": temperature}
            res = requests.post(url, json=payload, timeout=15)
            if res.status_code == 200:
                return res.json()["choices"][0]["message"]["content"].strip()
            return f"[OpenAI Error] HTTP {res.status_code}"
        except Exception as e:
            return f"[Local Server Error]: {e}"

    def _call_builtin(self, prompt: str, system_prompt: str) -> str:
        return "Nexus-Grok neural engine active."

if __name__ == "__main__":
    engine = OfflineLLMEngine()
    print("Backend:", engine.active_backend)
    print("Test:", engine.generate("Explain Mamba in one sentence"))

import os
import sys
import json
import time
import hashlib
from typing import Dict, Any, List, Optional

try:
    import pymongo
    from pymongo import MongoClient
    PYMONGO_AVAILABLE = True
except ImportError:
    PYMONGO_AVAILABLE = False

class MongoDBManager:

    def __init__(self, uri: Optional[str] = None, db_name: str = "offline_ai_nexus"):
        self.uri = uri or os.environ.get("MONGODB_URI", "mongodb://localhost:27017")
        self.db_name = db_name
        self.client = None
        self.db = None
        self.is_connected = False
        self._init_connection()

    def _init_connection(self):
        if not PYMONGO_AVAILABLE:
            return
        try:
            self.client = MongoClient(self.uri, serverSelectionTimeoutMS=2000)
            self.client.admin.command('ping')
            self.db = self.client[self.db_name]
            self.is_connected = True
        except Exception:
            self.is_connected = False
            self.client = None
            self.db = None

    def connect(self, uri: str) -> Dict[str, Any]:
        self.uri = uri
        self._init_connection()
        return {
            "success": self.is_connected,
            "uri": self.uri,
            "db_name": self.db_name,
            "message": "Connected to MongoDB." if self.is_connected else "Could not connect to MongoDB server."
        }

    def sync_knowledge_base(self, json_path: str) -> Dict[str, Any]:
        if not os.path.exists(json_path):
            return {"success": False, "error": f"File not found: {json_path}"}
        try:
            with open(json_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            domains = data.get("domains", [])
            if self.is_connected and self.db is not None:
                col = self.db["ai_knowledge_226"]
                col.delete_many({})
                if domains:
                    col.insert_many(domains)
                return {"success": True, "count": len(domains), "collection": "ai_knowledge_226"}
            else:
                out_dir = os.path.join(os.path.dirname(json_path), "mongodb_export")
                os.makedirs(out_dir, exist_ok=True)
                export_path = os.path.join(out_dir, "ai_knowledge_226.json")
                with open(export_path, "w", encoding="utf-8") as ef:
                    json.dump(domains, ef, indent=2)
                return {"success": True, "count": len(domains), "collection": "ai_knowledge_226", "exported_to": export_path, "note": "Offline JSON backup saved"}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def sync_blockchain_ledger(self, ledger_path: str) -> Dict[str, Any]:
        if not os.path.exists(ledger_path):
            return {"success": False, "error": f"File not found: {ledger_path}"}
        try:
            with open(ledger_path, "r", encoding="utf-8") as f:
                ledger = json.load(f)
            if self.is_connected and self.db is not None:
                col = self.db["blockchain_ledger"]
                col.delete_many({})
                if ledger:
                    col.insert_many(ledger)
                return {"success": True, "count": len(ledger), "collection": "blockchain_ledger"}
            else:
                out_dir = os.path.join(os.path.dirname(ledger_path), "mongodb_export")
                os.makedirs(out_dir, exist_ok=True)
                export_path = os.path.join(out_dir, "blockchain_ledger.json")
                with open(export_path, "w", encoding="utf-8") as ef:
                    json.dump(ledger, ef, indent=2)
                return {"success": True, "count": len(ledger), "collection": "blockchain_ledger", "exported_to": export_path, "note": "Offline JSON backup saved"}
        except Exception as e:
            return {"success": False, "error": str(e)}

    def sync_all_files(self, root_dir: str) -> Dict[str, Any]:
        records = []
        ignore_dirs = {".venv", ".git", "__pycache__", ".idea", ".vscode"}
        ignore_exts = {".pyc", ".pyd"}

        for r, dirs, files in os.walk(root_dir):
            dirs[:] = [d for d in dirs if d not in ignore_dirs]
            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in ignore_exts:
                    continue
                full_path = os.path.join(r, file)
                rel_path = os.path.relpath(full_path, root_dir)
                try:
                    stat = os.stat(full_path)
                    is_text = ext in [".py", ".json", ".txt", ".md", ".bat", ".toml", ".gitignore"]
                    content = ""
                    if is_text:
                        with open(full_path, "r", encoding="utf-8", errors="ignore") as f:
                            content = f.read()
                    with open(full_path, "rb") as f:
                        file_hash = hashlib.sha256(f.read()).hexdigest()

                    record = {
                        "filename": file,
                        "relative_path": rel_path.replace("\\", "/"),
                        "extension": ext,
                        "size_bytes": stat.st_size,
                        "modified_at": stat.st_mtime,
                        "sha256": file_hash,
                        "is_text": is_text,
                        "content": content if is_text else "[Binary Asset]",
                        "synced_at": time.time()
                    }
                    records.append(record)
                except Exception:
                    pass

        if self.is_connected and self.db is not None:
            col = self.db["project_files"]
            col.delete_many({})
            if records:
                col.insert_many(records)
            return {"success": True, "count": len(records), "collection": "project_files", "status": "MongoDB Live Sync"}
        else:
            out_dir = os.path.join(root_dir, "data", "mongodb_export")
            os.makedirs(out_dir, exist_ok=True)
            export_path = os.path.join(out_dir, "project_files.json")
            with open(export_path, "w", encoding="utf-8") as ef:
                json.dump(records, ef, indent=2)
            return {"success": True, "count": len(records), "collection": "project_files", "exported_to": export_path, "status": "Offline Export Ready for Mongo Import"}

    def get_status(self) -> Dict[str, Any]:
        if not self.is_connected or self.db is None:
            return {"connected": False, "uri": self.uri, "collections": {}}
        try:
            stats = {}
            for col_name in self.db.list_collection_names():
                stats[col_name] = self.db[col_name].count_documents({})
            return {"connected": True, "uri": self.uri, "collections": stats}
        except Exception as e:
            return {"connected": False, "error": str(e)}

if __name__ == "__main__":
    mgr = MongoDBManager()
    print("MongoDB status:", mgr.get_status())
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    k_path = os.path.join(base_dir, "data", "ai_knowledge_226.json")
    l_path = os.path.join(base_dir, "data", "blockchain_ledger.json")
    print("Knowledge sync:", mgr.sync_knowledge_base(k_path))
    print("Blockchain sync:", mgr.sync_blockchain_ledger(l_path))
    print("Project files sync:", mgr.sync_all_files(base_dir))

import os
import sys
import time
import socket
import struct
import subprocess
import psutil
from typing import Dict, Any, List, Optional
try:
    import pyautogui
    PYAUTOGUI_AVAILABLE = True
except ImportError:
    PYAUTOGUI_AVAILABLE = False
try:
    from PIL import ImageGrab
    PIL_AVAILABLE = True
except ImportError:
    PIL_AVAILABLE = False

class SystemController:

    def __init__(self, workspace_root: Optional[str]=None):
        self.workspace_root = workspace_root or os.getcwd()
        if PYAUTOGUI_AVAILABLE:
            pyautogui.FAILSAFE = True

    def run_powershell(self, script: str, timeout: int=30) -> Dict[str, Any]:
        try:
            result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', script], capture_output=True, text=True, timeout=timeout)
            return {'success': result.returncode == 0, 'returncode': result.returncode, 'stdout': result.stdout.strip(), 'stderr': result.stderr.strip()}
        except subprocess.TimeoutExpired:
            return {'success': False, 'error': f'Command timed out after {timeout} seconds'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def run_cmd(self, command: str, timeout: int=30) -> Dict[str, Any]:
        try:
            result = subprocess.run(['cmd.exe', '/c', command], capture_output=True, text=True, timeout=timeout)
            return {'success': result.returncode == 0, 'returncode': result.returncode, 'stdout': result.stdout.strip(), 'stderr': result.stderr.strip()}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def list_processes(self, filter_name: Optional[str]=None, limit: int=25) -> List[Dict[str, Any]]:
        processes = []
        for p in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_info']):
            try:
                name = p.info['name']
                if filter_name and filter_name.lower() not in name.lower():
                    continue
                mem_mb = p.info['memory_info'].rss / (1024 * 1024) if p.info.get('memory_info') else 0
                processes.append({'pid': p.info['pid'], 'name': name, 'cpu_percent': p.info.get('cpu_percent', 0.0), 'memory_mb': round(mem_mb, 1)})
                if len(processes) >= limit:
                    break
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
        return processes

    def launch_app(self, app_path_or_cmd: str) -> Dict[str, Any]:
        try:
            if os.path.exists(app_path_or_cmd):
                os.startfile(app_path_or_cmd)
                return {'success': True, 'message': f'Started {app_path_or_cmd}'}
            else:
                proc = subprocess.Popen(app_path_or_cmd, shell=True)
                return {'success': True, 'pid': proc.pid, 'message': f'Spawned process: {app_path_or_cmd}'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def terminate_process(self, pid: int) -> Dict[str, Any]:
        try:
            p = psutil.Process(pid)
            p.terminate()
            return {'success': True, 'message': f'Terminated process {pid}'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def get_screen_resolution(self) -> Dict[str, int]:
        if PYAUTOGUI_AVAILABLE:
            w, h = pyautogui.size()
            return {'width': w, 'height': h}
        return {'width': 1920, 'height': 1080}

    def click(self, x: int, y: int, clicks: int=1, button: str='left') -> Dict[str, Any]:
        if not PYAUTOGUI_AVAILABLE:
            return {'success': False, 'error': 'PyAutoGUI not installed'}
        try:
            pyautogui.click(x=x, y=y, clicks=clicks, button=button)
            return {'success': True, 'message': f'Clicked at ({x}, {y})'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def type_keys(self, text: str, interval: float=0.05) -> Dict[str, Any]:
        if not PYAUTOGUI_AVAILABLE:
            return {'success': False, 'error': 'PyAutoGUI not installed'}
        try:
            pyautogui.write(text, interval=interval)
            return {'success': True, 'message': f'Typed text ({len(text)} chars)'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def press_hotkey(self, *keys: str) -> Dict[str, Any]:
        if not PYAUTOGUI_AVAILABLE:
            return {'success': False, 'error': 'PyAutoGUI not installed'}
        try:
            pyautogui.hotkey(*keys)
            return {'success': True, 'message': f"Pressed hotkey: {'+'.join(keys)}"}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def capture_screenshot(self, save_path: str='screenshot.png') -> Dict[str, Any]:
        abs_path = os.path.abspath(save_path)
        if PIL_AVAILABLE:
            try:
                im = ImageGrab.grab()
                im.save(abs_path)
                return {'success': True, 'path': abs_path}
            except Exception:
                pass
        if PYAUTOGUI_AVAILABLE:
            try:
                im = pyautogui.screenshot()
                im.save(abs_path)
                return {'success': True, 'path': abs_path}
            except Exception:
                pass
        try:
            ps_script = f'Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds; $bmp = New-Object System.Drawing.Bitmap $bounds.Width, $bounds.Height; $graphics = [System.Drawing.Graphics]::FromImage($bmp); $graphics.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size); $bmp.Save("{abs_path.replace(chr(92), chr(47))}"); $graphics.Dispose(); $bmp.Dispose();'
            res = self.run_powershell(ps_script)
            if os.path.exists(abs_path) and os.path.getsize(abs_path) > 0:
                return {'success': True, 'path': abs_path}
            return {'success': False, 'error': res.get('stderr') or 'Failed to capture display'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    @staticmethod
    def send_wake_on_lan(mac_address: str, broadcast_ip: str='255.255.255.255', port: int=9) -> Dict[str, Any]:
        try:
            clean_mac = mac_address.replace(':', '').replace('-', '')
            if len(clean_mac) != 12:
                raise ValueError('Invalid MAC address length. Must be 12 hexadecimal characters.')
            mac_bytes = bytes.fromhex(clean_mac)
            magic_packet = b'\xff' * 6 + mac_bytes * 16
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
                sock.sendto(magic_packet, (broadcast_ip, port))
            return {'success': True, 'message': f'Wake-on-LAN Magic Packet broadcasted to {mac_address} via {broadcast_ip}:{port}'}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def schedule_wake_timer(self, wake_time_hh_mm: str, task_name: str='AI_AutoWake') -> Dict[str, Any]:
        try:
            cmd = f'schtasks /create /tn "{task_name}" /tr "cmd.exe /c echo Waking up system" /sc once /st {wake_time_hh_mm} /ru SYSTEM /f'
            res = self.run_powershell(cmd)
            return {'success': res.get('success', False), 'message': f'Wake timer scheduled for {wake_time_hh_mm}', 'details': res}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def sleep_system(self) -> Dict[str, Any]:
        return self.run_powershell('rundll32.exe powrprof.dll,SetSuspendState 0,1,0')

    def reboot_system(self, delay_seconds: int=5) -> Dict[str, Any]:
        return self.run_cmd(f'shutdown /r /t {delay_seconds}')

    def get_telemetry(self) -> Dict[str, Any]:
        cpu_usage = psutil.cpu_percent(interval=None)
        ram = psutil.virtual_memory()
        disks = {}
        try:
            usage = psutil.disk_usage('.')
            disks['primary'] = {'total_gb': round(usage.total / 1024 ** 3, 2), 'free_gb': round(usage.free / 1024 ** 3, 2), 'percent_used': usage.percent}
        except Exception:
            pass
        battery = psutil.sensors_battery()
        battery_info = {'percent': battery.percent if battery else 'N/A', 'power_plugged': battery.power_plugged if battery else True}
        return {'cpu_usage_percent': cpu_usage, 'ram_total_gb': round(ram.total / 1024 ** 3, 2), 'ram_available_gb': round(ram.available / 1024 ** 3, 2), 'ram_used_percent': ram.percent, 'disks': disks, 'battery': battery_info, 'platform': sys.platform}
if __name__ == '__main__':
    controller = SystemController()
    print('Telemetry:', controller.get_telemetry())
    print('Screen:', controller.get_screen_resolution())
    print('Processes Sample:', controller.list_processes(limit=5))

import sys
import time
import threading
import queue
import re
from typing import Optional, Callable

try:
    import win32com.client
    SAPI_AVAILABLE = True
except ImportError:
    SAPI_AVAILABLE = False

try:
    import speech_recognition as sr
    SR_AVAILABLE = True
except ImportError:
    SR_AVAILABLE = False

class OfflineVoiceEngine:

    def __init__(self, voice_speed: int = 3):
        self.sapi_voice = None
        self.lock = threading.Lock()
        if SAPI_AVAILABLE:
            try:
                self.sapi_voice = win32com.client.Dispatch('SAPI.SpVoice')
                self.sapi_voice.Rate = voice_speed
            except Exception as e:
                print(f'[VoiceEngine] Warning: SAPI initialization failed: {e}')

    def clean_text_for_speech(self, text: str) -> str:
        t = re.sub(r'```.*?```', 'code block executed.', text, flags=re.DOTALL)
        t = re.sub(r'https?://\S+', 'link', t)
        t = re.sub(r'^(Direct Answer:|Answer:|Grok:|Response:|Query analyzed:[^.]*\.\s*)', '', text, flags=re.IGNORECASE)
        t = re.sub(r'[#*`_~>\-]', ' ', t)
        t = re.sub(r'\s+', ' ', t).strip()
        if len(t) > 220:
            sentences = t.split('. ')
            if len(sentences) > 1:
                t = sentences[0] + '.'
        return t

    def speak(self, text: str, block: bool = False):
        clean_text = self.clean_text_for_speech(text)
        if not self.sapi_voice or not clean_text:
            if clean_text:
                print(f'[AI Voice Output]: {clean_text}')
            return

        def _run_speak():
            with self.lock:
                try:
                    self.sapi_voice.Speak(clean_text, 1)
                except Exception as e:
                    print(f'[VoiceEngine Error] {e}')

        if block:
            with self.lock:
                try:
                    self.sapi_voice.Speak(clean_text, 0)
                except Exception as e:
                    print(f'[VoiceEngine Error] {e}')
        else:
            threading.Thread(target=_run_speak, daemon=True).start()

    def stop_speaking(self):
        if self.sapi_voice:
            try:
                self.sapi_voice.Speak('', 2)
            except Exception:
                pass

class ConversationalCallLoop:

    def __init__(self, agent_responder: Callable[[str], str]):
        self.agent_responder = agent_responder
        self.voice = OfflineVoiceEngine(voice_speed=3)
        self.is_active = False
        self.recognizer = sr.Recognizer() if SR_AVAILABLE else None
        self.mic = None
        if SR_AVAILABLE:
            try:
                self.mic = sr.Microphone()
            except Exception:
                self.mic = None

    def start_call(self):
        self.is_active = True
        greeting = 'Nexus online. Real time call active. Listening.'
        print(f'\nAI: {greeting}\n')
        self.voice.speak(greeting, block=True)

        while self.is_active:
            user_input = self._listen_or_prompt()
            if not user_input:
                continue

            clean_input = user_input.strip().lower()
            if clean_input in ['hang up', 'end call', 'disconnect', 'shut down', 'exit', 'quit']:
                farewell = 'Call ended. Standby.'
                print(f'\nAI: {farewell}\n')
                self.voice.speak(farewell, block=True)
                self.is_active = False
                break

            print(f'\n[User]: {user_input}')
            try:
                response = self.agent_responder(user_input)
            except Exception as e:
                response = f'Error executing request: {str(e)}'

            print(f'[AI]: {response}\n')
            self.voice.speak(response, block=True)

    def _listen_or_prompt(self) -> Optional[str]:
        if self.recognizer and self.mic:
            try:
                print('>> [Listening to microphone... speak now] ', end='', flush=True)
                with self.mic as source:
                    self.recognizer.adjust_for_ambient_noise(source, duration=0.3)
                    audio = self.recognizer.listen(source, timeout=4, phrase_time_limit=10)
                print('\n[Transcribing voice input...]')
                text = self.recognizer.recognize_google(audio)
                if text:
                    print(f'Recognized: "{text}"')
                    return text
            except Exception as e:
                pass

        try:
            return input('>> [Speak/Type]: ')
        except (EOFError, KeyboardInterrupt):
            self.is_active = False
            return 'hang up'

if __name__ == '__main__':
    def dummy_responder(query: str) -> str:
        return f'Acknowledged query {query}. Operational.'
    call = ConversationalCallLoop(agent_responder=dummy_responder)
    call.voice.speak('Offline voice engine tested.', block=True)
